// Historical source assertions use the preserved original cohort; current sources have a separate census test.
const {historicalRead,historicalJson,skipHistoricalSource}=require('./published-fixture.cjs');
if(skipHistoricalSource(__filename))return;
/* eslint-disable @typescript-eslint/no-require-imports -- Uses the existing CJS integration-test runner. */
// Integration contract for generated BYE choices, independent of the map rendering.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '../..');
const publicDir = path.resolve(process.env.QOE_PUBLIC_DIR || path.join(root, 'public'));
const read = relative => JSON.parse(historicalRead(path.join(publicDir, relative), 'utf8'));

test('BYE choices expose selection evidence without changing the original call or GNSS position', () => {
  const manifest = read('voice-1030.json');
  const methods = new Set(['unique', 'mdt', 'first']);
  const counts = {unique: 0, mdt: 0, first: 0};
  for (const date of manifest.meta.dates) {
    const overview = read('analyst-overview/MDT/' + date + '.json');
    assert.equal(overview.sourceRevision, manifest.meta.revision);
    const calls = new Map(overview.calls.map(call => [call.id, call]));
    const seen = new Set();
    for (const point of overview.callLocations) {
      assert(!seen.has(point.callId)); seen.add(point.callId);
      const call = calls.get(point.callId);
      assert(call);
      assert.equal(point.mos, call.mos);
      if (!point.byeRuId) continue;
      assert(methods.has(point.byeSelectionMethod), 'every BYE reference declares how its RU was selected');
      assert(Number.isInteger(point.byeCandidateCount) && point.byeCandidateCount >= 1);
      if (point.byeSelectionMethod === 'unique') assert.equal(point.byeCandidateCount, 1);
      if (point.byeSelectionMethod === 'mdt') {
        assert.equal(point.byeSelectionMdtRu, point.byeRuId);
        assert(point.byeSelectionDeltaSeconds >= -1 && point.byeSelectionDeltaSeconds <= 30);
      }
      assert.equal(point.byeCellId, call.endCellId);
      if (call.endRat) assert.equal(point.byeTechnology, call.endRat);
      if (point.evidence === 'bye-cell') {
        assert.equal(point.positionQuality, 'bye-cell-site');
        assert.equal(point.observedAt, null, 'station selection never invents measured UE coordinates');
        assert.equal(point.usedSiteCount, null);
      } else {
        assert.equal(point.representativeBasis, 'cdr-end-nearest');
        assert(Number.isFinite(point.byeStationLat) && Number.isFinite(point.byeStationLon));
      }
      counts[point.byeSelectionMethod]++;
    }
  }
  assert(counts.mdt > 0, 'same-call MDT RU disambiguation is actually used');
  assert(counts.first > 0, 'ambiguous calls without usable MDT remain visible through first-candidate selection');
});

test('the six previously ambiguous poor Cell 804622 calls select the MDT RU', () => {
  const overview = read('analyst-overview/MDT/2026-10-30.json');
  const starts = new Set(['18:39:45', '18:43:56', '13:30:46', '15:16:06', '19:28:49', '20:39:14']);
  const calls = overview.calls.filter(call => call.endCellId === '804622' && starts.has(call.start));
  assert.equal(calls.length, 6);
  const points = new Map(overview.callLocations.map(point => [point.callId, point]));
  for (const call of calls) {
    const point = points.get(call.id);
    assert(point, 'previously ambiguous example is now mapped');
    assert.equal(point.byeSelectionMethod, 'mdt');
    assert.equal(point.byeRuId, 'RRSL01005T');
    assert.equal(point.byeCandidateCount, 3);
    assert.equal(point.lat, 37.48320167);
    assert.equal(point.lon, 127.06033083);
  }
});
